reference_solution:
def smallest_numeric_value_string(n, k):
 answer=['a']*n;remaining=k-n
 for index in range(n-1,-1,-1):
  increase=min(25,remaining);answer[index]=chr(ord('a')+increase);remaining-=increase
 return ''.join(answer)

